def count_stepping_numbers(low: str, high: str) -> int:
    MOD = 10**9 + 7

    def count_up_to(s: str) -> int:
        """Count stepping numbers in [1, int(s)]."""
        n = len(s)
        # dp[length][last_digit][tight][started]
        # We'll use memoization with recursion
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos: int, last_digit: int, tight: bool, started: bool) -> int:
            # pos: current position (0-indexed)
            # last_digit: the last digit placed (0-9), or -1 if not started
            # tight: whether we are still matching the prefix of s
            # started: whether we have started placing digits (i.e., not all zeros so far)
            if pos == n:
                return 1 if started else 0

            limit = int(s[pos]) if tight else 9
            total = 0
            for d in range(limit + 1):
                new_tight = tight and (d == limit)
                if not started:
                    if d == 0:
                        # Still not started
                        total += dp(pos + 1, -1, new_tight, False)
                    else:
                        # Start with digit d
                        total += dp(pos + 1, d, new_tight, True)
                else:
                    # Already started, check stepping condition
                    if abs(d - last_digit) == 1:
                        total += dp(pos + 1, d, new_tight, True)
            return total % MOD

        return dp(0, -1, True, False)

    result = (count_up_to(high) - count_up_to(low)) % MOD
    # Adjust if negative
    if result < 0:
        result += MOD
    return result
